dependencies:
--- identity_shard.gd ---
extends Area3D

@export_category("Shard Properties")
@export_var(name: "Effect Strength", type: float, default: 5.0, hint: "Magnitude of physics effect")
var effect_strength: float = 5.0
@export_var(name: "Shard Lifetime", type: float, default: 3.0, hint: "Duration before shard despawns")
var shard_lifetime: float = 3.0
@export_var(name: "Effect Type", type: int, default: 0, hint_string: "0: Repulsion, 1: Drag, 2: Gravity Shift")
var effect_type: int = 0 # 0: Repulsion, 1: Drag, 2: Gravity Shift (simplified)
@export_var(name: "Gravity Shift Direction", type: Vector3, default: Vector3(0, -1, 0), hint: "Direction for gravity shift effect")
var gravity_shift_direction: Vector3 = Vector3(0, -1, 0)

var _time_elapsed: float = 0.0
var _initial_direction: Vector3 = Vector3.ZERO

func _ready() -> void:
	set_physics_process(true)

func initialize_shard(direction: Vector3) -> void:
	_initial_direction = direction

func _physics_process(delta: float) -> void:
	_time_elapsed += delta
	if _time_elapsed >= shard_lifetime:
		queue_free()
		return

	var overlapping_bodies: Array[Node3D] = get_overlapping_bodies()
	for body in overlapping_bodies:
		if body is CharacterBody3D:
			if body.has_method("is_hunter") and body.is_hunter():
				if body.has_method("absorb_shard"):
					body.absorb_shard(self)
					queue_free()
					return

func get_shard_effect_force(target_position: Vector3, target_velocity: Vector3) -> Vector3:
	var effect_vector: Vector3 = Vector3.ZERO
	match effect_type:
		0: # Repulsion
			effect_vector = (target_position - global_position).normalized() * effect_strength
		1: # Drag
			effect_vector = -target_velocity.normalized() * effect_strength
		2: # Gravity Shift
			effect_vector = gravity_shift_direction.normalized() * effect_strength
	return effect_vector
